            'клок': ['клочья', 'клоки'],
            'князь': ['князи', 'князья'],
            'кол': ['колы', 'колья'], // TODO: можно разделить на омонимы
            'месяц': ['месяцы'],
            'полдень': ['полдни', 'полудни'],
            'татарин': ['татары'],
            'хозяин': ['хозяева'],
            'цветок': ['цветки', 'цветы'],
